import 'dart:math';
import 'package:flutter_test/flutter_test.dart';
import 'package:memora/dual_world_engine.dart';
void main(){
 test('singular elements do not belong to ordinary elemental mastery',(){final elemental={'spiritClass':'elementalist','elements':['fire']};expect(DualState.elementMastery(elemental,'gravity'),0);expect(DualState.elementMastery({...elemental,'singularElement':'gravity'},'gravity'),100);expect(DualState.elementalAffinity(elemental,{'element':'gravity','affinity':'neutral'}),0);});
 test('fusion chance grows with intelligence and rank; failure preserves originals',(){final s=DualState();final a={'id':'a','name':'A','type':'attack','magic':false,'rank':'E','damage':6,'cost':2},b={'id':'b','name':'B','type':'attack','magic':false,'rank':'E','damage':8,'cost':2};s.skills.addAll(['a','b']);s.cash=1000;s.intelligence=29;expect(s.fusionChance(a,b),0);expect(s.fuse(a,b),false);expect(s.cash,1000);s.intelligence=30;expect(s.fusionChance(a,b),25);var seed=0;while(Random(seed).nextInt(100)<25){seed++;}expect(s.fuse(a,b,random:Random(seed)),false);expect(s.cash,500);expect(s.skills.containsAll(['a','b']),true);s.cash=1000;s.intelligence=60;expect(s.fusionChance(a,b),100);expect(s.fuse(a,b),true);expect(s.skills.containsAll(['a','b']),true);});
 test('student growth is slow, bounded by potential and uses time since unlock',(){final sk={'id':'a','rank':'E','damage':10,'cost':2,'price':50,'minClasses':0};final ordinary={'initialRank':'E','potentialRank':'D'},talented={'initialRank':'E','potentialRank':'SS'};expect(DualState.npcTechnique(sk,ordinary,5)['rank'],'E');expect(DualState.npcTechnique(sk,ordinary,30)['rank'],'D');expect(DualState.npcTechnique(sk,talented,6)['rank'],'C');expect(DualState.npcTechnique(sk,talented,6)['damage'],14);expect(DualState.npcTechnique({...sk,'minClasses':6},talented,6)['rank'],'E');expect(DualState.npcTechniqueAvailable({...sk,'minClasses':6},ordinary,6),false);expect(DualState.npcTechniqueAvailable({...sk,'minClasses':6},talented,6),true);});
 test('only learned techniques can ascend or fuse; results persist until return',(){final s=DualState();s.intelligence=120;s.cash=10000;final a={'id':'a','name':'A','type':'attack','magic':false,'rank':'E','damage':6,'cost':2},b={'id':'b','name':'B','type':'attack','magic':false,'rank':'E','damage':8,'cost':2};expect(s.upgradeTechnique(a),false);s.skills.addAll(['a','b']);expect(s.upgradeTechnique(a),true);expect(s.effectiveTechnique(a)['damage'],9);expect(s.fuse(a,b),true);expect(DualState.fromJson(s.toJson()).fusedSkills.length,1);expect(s.returnToBeginning().fusedSkills,isEmpty);});
 test('appraisal needs both intelligence and permanent paid upgrades within a life',(){final s=DualState();s.cash=500;expect(s.refineAppraisal(),false);s.intelligence=20;expect(s.refineAppraisal(),true);expect(s.appraisalRank,'D');expect(DualState.fromJson(s.toJson()).appraisalRank,'D');expect(s.returnToBeginning().appraisalRank,'E');});
 test('innate spiritual rank is independent of intelligence',(){expect(DualState.spiritualRank(85,5),DualState.spiritualRank(85,300));});
 test('weapon requirements and return reset equipment',(){final s=DualState();final w={'id':'w','price':30,'minStrength':6,'minIntelligence':5,'strengthBonus':5,'magicBonus':0,'defenseBonus':1};s.cash=30;s.world='trade';s.place='Armería';expect(s.buyWeapon(w),true);s.world='school';s.place='Dormitorio';expect(s.equipWeapon(w),false);s.strength=6;expect(s.equipWeapon(w),true);expect(DualState.fromJson(s.toJson()).weaponStrength,5);expect(s.returnToBeginning().weapons,isEmpty);});
 test('power ranks grow to their potential; elementalists master ordinary elements only',(){expect(DualState.combatRank({'initialRank':'D','potentialRank':'A'},12),'A');expect(DualState.combatRank({'initialRank':'D','potentialRank':'C'},30),'C');final p={'spiritClass':'elementalist','elements':['fire']};expect(DualState.elementMastery(p,'water'),100);expect(DualState.elementMastery(p,'void'),0);expect(DualState.elementMastery(p,'divine'),0);expect(DualState.elementMastery({'elements':['fire','water']},'water'),65);expect(DualState.elementMastery({'elements':['fire']},'water'),25);});
 test('spiritual capacity follows class, not boss status',(){expect(DualState.spiritualCapacity({'boss':true,'spiritualAffinity':100},300),1);expect(DualState.spiritualCapacity({'race':'elf','spiritualAffinity':100},300),5);expect(DualState.spiritualCapacity({'spiritClass':'specialist','spiritualAffinity':100},300),10);expect(DualState.spiritualCapacity({'spiritClass':'elementalist','spiritualAffinity':100},300),15);});
 test('elementalists master common elements but cannot access restricted elements',(){final p={'spiritClass':'elementalist','spiritualAffinity':85,'elements':['fire','wind']};expect(DualState.elementalAffinity(p,{'element':'fire','affinity':'dragon'}),100);expect(DualState.elementalAffinity(p,{'element':'water','affinity':'neutral'}),100);expect(DualState.elementalAffinity(p,{'element':'void','affinity':'neutral'}),0);});
 test('external books grant exact five points and preserve progress after return',(){final s=DualState();expect(s.addReadingBook('Libro','Autora',300,'Finanzas'),true);final key=DualState.bookKey('Libro','Autora');expect(s.logReading(key,30),500);expect(s.intelligence,5);expect(s.logReading(key,300),4500);expect(s.intelligence,10);expect(s.logReading(key,300),isNull);expect(s.returnToBeginning().readingLog[key]!['page'],300);});
 test('repeatable monster XP scales with level',(){final s=DualState();expect(s.victoryXp({'repeatable':true,'level':4,'hp':100},false),greaterThan(s.victoryXp({'repeatable':true,'level':1,'hp':20},true)));});
 test('reading awards five points per book without daily cap or repeats',(){final s=DualState();for(var b=0;b<30;b++){for(var p=0;p<5;p++){expect(s.pageReward(p,5),1);expect(s.read('b'+b.toString(),p,5),true);}}expect(s.intelligence,155);expect(s.read('b0',0,5),false);expect(s.returnToBeginning().intelligence,155);});
 test('return resets both worlds and retains intelligence and anti-duplicate records',(){final s=DualState();s.cash=300;s.skills.add('blade');s.strength=20;s.intelligence=25;s.workoutDate='2026-11-27';s.readPages['book']=5;s.deadStudents.add('x');s.spirits.add('fox');final r=s.returnToBeginning();expect(r.intelligence,25);expect(r.cash,0);expect(r.skills,isEmpty);expect(r.strength,4);expect(r.deadStudents,isEmpty);expect(r.spirits,isEmpty);expect(r.readPages['book'],5);expect(r.workoutDate,'2026-11-27');});
 test('spirit requires strict intelligence and rescue deadline',(){final s=DualState();s.place='Dungeon';final spirit={'id':'fox','intelligence':5};expect(s.capture(spirit),false);s.intelligence=6;expect(s.capture(spirit),true);s.rewardExam('a',true);s.resolveFates([{'person':'x','deadline':1}]);expect(s.deadStudents.contains('x'),true);});
 test('racial techniques must be acquired; drain, healing and sealing work',(){final s=DualState();final enemy={'id':'v','hp':50,'attack':4,'defense':0,'xp':20};final drain={'id':'bite','type':'drain','magic':false,'cost':1,'damage':8};s.startBattle(0,50);expect(s.action(drain,enemy),contains('adquirido'));s.skills.add('bite');s.hp=10;s.action(drain,enemy);expect(s.enemyHp,lessThan(50));s.skills.add('seal');s.action({'id':'seal','type':'hypnosis','magic':true,'cost':1,'damage':4},enemy);expect(s.enemyWeakTurns,1);final copy=DualState.fromJson(s.toJson());expect(copy.enemyWeakTurns,1);});
 test('student techniques become available with completed classes',(){final s=DualState();final sk={'minClasses':3};expect(s.skillAvailable(sk),false);for(var i=0;i<3;i++){s.rewardExam('l'+i.toString(),true);}expect(s.skillAvailable(sk),true);expect(s.skillAvailable({'minClasses':6}),false);});
 test('world travel, reading once and exercise cap',(){final s=DualState();expect(s.travel(),true);expect(s.world,'trade');s.place='Mercado';expect(s.travel(),false);expect(s.read('book',0,5),true);expect(s.read('book',0,5),false);for(var i=1;i<5;i++){s.read('book',i,5);}expect(s.intelligence,10);expect(s.workout('2026-11-27'),true);expect(s.workout('2026-11-27'),false);expect(s.workout('2026-11-26'),false);expect(s.strength,6);});
 test('cash is conserved and skills cannot be purchased twice',(){final s=DualState();s.commission();final r=s.trade(3,12,2,5,2)!;expect(r['profit'],12);expect(s.cash,37);expect(s.stock,1);s.appraised.add('shield');expect(s.buySkill('shield',30),true);expect(s.buySkill('shield',30),false);expect(s.cash,7);});
 test('starts powerless and choices persist, gate secrets, and cannot farm trust',(){final s=DualState();expect(s.skills,isEmpty);expect(s.reputation,-30);final e={'id':'meeting','world':'school','place':'Dormitorio','person':'lyra','choices':[{'id':'help','trust':8,'affection':3,'flag':'promise','outcome':'Gracias'}]};final ch=(e['choices'] as List).first as Map;expect(s.eligible(e),true);expect(s.chooseEvent(e,ch),true);expect(s.chooseEvent(e,ch),false);expect(s.relationship('lyra'),8);final saved=DualState.fromJson(s.toJson());expect(saved.flags.contains('promise'),true);expect(saved.warmth('lyra'),3);expect(saved.eligible(e),false);});
 test('exams unlock rewards once and persisted state survives',(){final s=DualState();expect(s.rewardExam('a',false),0);expect(s.rewardExam('a',true),90);expect(s.rewardExam('a',true),90);expect(s.cash,0);expect(s.claimGuild('a'),90);expect(s.claimGuild('a'),0);final copy=DualState.fromJson(s.toJson());expect(copy.grades['a'],90);expect(copy.cash,90);});
 test('royal factions are exclusive, neutral preserves access, and allegiance persists',(){
   final s=DualState();s.place='Consejo';expect(s.chooseRoyalFaction('evelyne'),true);expect(s.royalStanding('evelyne'),8);expect(s.royalStanding('aldren'),-8);expect(s.royalEventAvailable('evelyne'),true);expect(s.royalEventAvailable('aldren'),false);expect(s.chooseRoyalFaction('aldren'),false);
   final saved=DualState.fromJson(s.toJson());expect(saved.royalAlignment,'evelyne');expect(saved.royalChoiceMade,true);
   final n=DualState();n.place='Palacio';expect(n.chooseRoyalFaction('neutral'),true);expect(n.royalEventAvailable('evelyne'),true);expect(n.royalEventAvailable('aldren'),true);expect(n.royalStanding('evelyne'),0);expect(n.royalStanding('aldren'),0);
 });
 test('frontier contracts award gold once for unique targets and repeatedly for hunts',(){
   final s=DualState();
   final unique={'id':'war_test','level':4,'hp':40,'xp':150,'goldReward':80};
   s.battleVictory(unique);expect(s.cash,80);expect(s.xp,150);
   s.battleVictory(unique);expect(s.cash,80);expect(s.xp,150);
   final hunt={'id':'hunt_test','level':2,'hp':20,'repeatable':true,'goldReward':20};
   s.battleVictory(hunt);s.battleVictory(hunt);expect(s.cash,120);expect(s.battleCounts['hunt_test'],2);
 });
 test('colossal raids support solo and finite squad resources and preserve save state',(){
   final s=DualState();s.place='Frente de guerra';s.flags.add('mercenary_member');
   final boss={'id':'colossus_test','raid':true,'level':20,'teamMinLevel':5,'hp':1000,'defense':10,'attack':80,'xp':14000};
   expect(s.startRaid(0,boss,withTeam:true),false);
   s.xp=500;expect(s.startRaid(0,boss,withTeam:true),true);expect(s.raidAllies.length,3);
   final energy=s.raidAllies.first['energy'] as int;expect(s.raidSupport(boss),greaterThan(0));expect(s.raidAllies.first['energy'],energy-3);
   expect(s.raidIntercept(80,boss),20);
   final saved=DualState.fromJson(s.toJson());expect(saved.raidAllies.length,3);expect(saved.raidAllies.first['energy'],energy-3);
   expect(saved.victoryXp(boss,true),14000);
   saved.enemyIndex=-1;expect(saved.startRaid(0,boss,withTeam:false),true);expect(saved.raidAllies,isEmpty);
 });
}
